package com.ecole.gestion_scolaire.transport.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="transport_driver") public class TransportDriver { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="last_name") public String lastName; @Column(name="first_name") public String firstName; public String phone; @Column(name="license_number") public String licenseNumber; @Column(name="license_expiry") public LocalDate licenseExpiry; public String status; public String notes; @Column(name="created_at") public OffsetDateTime createdAt; @Column(name="updated_at") public OffsetDateTime updatedAt; @PrePersist void p(){var n=OffsetDateTime.now();createdAt=n;updatedAt=n;if(status==null)status="ACTIVE";} @PreUpdate void u(){updatedAt=OffsetDateTime.now();} }
